package com.deathtracker;

import java.util.ArrayList;
import java.util.List;

/** A durable snapshot; values are fixed at the moment the death was recorded. */
public class DeathRecord
{
    public String id;
    public long timestamp;
    public String player;
    public int world;
    public int x;
    public int y;
    public int plane;
    public int region;
    public boolean instance;
    public String opponent;
    public String accountType;
    public boolean skulled;
    public boolean protectItem;
    public List<TrackedItem> equipment = new ArrayList<>();
    public List<TrackedItem> inventory = new ArrayList<>();
    public long carriedValue;
    public Long estimatedGraveFee;
    public String estimateNote;
    public String screenshot;
    public Long actualReclaimFee;
    public Long actualItemLoss;
    public Long actualOtherCost;
    public String reclaimMethod;
    public String notes;

    public Long actualTotal()
    {
        if (actualReclaimFee == null && actualItemLoss == null && actualOtherCost == null)
        {
            return null;
        }
        return zero(actualReclaimFee) + zero(actualItemLoss) + zero(actualOtherCost);
    }

    private static long zero(Long value)
    {
        return value == null ? 0L : value;
    }
}

package com.deathtracker;

import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.util.Iterator;
import javax.imageio.ImageIO;
import javax.imageio.ImageReader;
import javax.imageio.stream.MemoryCacheImageInputStream;
import javax.imageio.stream.MemoryCacheImageOutputStream;
import net.runelite.client.util.Filepath;

/** PNG access stays within the plugin directory; ImageIO never uses a disk cache. */
final class DeathScreenshot
{
    private DeathScreenshot()
    {
    }

    static void save(Image image, Filepath path) throws IOException
    {
        BufferedImage copy = new BufferedImage(image.getWidth(null), image.getHeight(null), BufferedImage.TYPE_INT_RGB);
        Graphics2D graphics = copy.createGraphics();
        try
        {
            graphics.drawImage(image, 0, 0, null);
        }
        finally
        {
            graphics.dispose();
        }
        try (OutputStream output = path.openOutputStream();
             MemoryCacheImageOutputStream png = new MemoryCacheImageOutputStream(output))
        {
            if (!ImageIO.write(copy, "png", png))
            {
                throw new IOException("PNG encoder is unavailable");
            }
        }
    }

    static BufferedImage read(Filepath path) throws IOException
    {
        if (path == null || !path.isFile())
        {
            throw new IOException("Screenshot is not available yet");
        }
        try (InputStream input = path.openInputStream();
             MemoryCacheImageInputStream png = new MemoryCacheImageInputStream(input))
        {
            Iterator<ImageReader> readers = ImageIO.getImageReadersByFormatName("png");
            if (!readers.hasNext())
            {
                throw new IOException("PNG decoder is unavailable");
            }
            ImageReader reader = readers.next();
            try
            {
                reader.setInput(png, true, true);
                return reader.read(0);
            }
            finally
            {
                reader.dispose();
            }
        }
    }
}

package com.deathtracker;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.nio.file.StandardCopyOption;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.runelite.client.util.Filepath;

/** Local, per-character JSON storage. Screenshots live in the same directory. */
final class DeathStore
{
    private final Gson gson;
    private final Filepath root;
    private Filepath directory;
    private final List<DeathRecord> records = new ArrayList<>();

    DeathStore(Gson gson, Filepath root)
    {
        this.gson = gson;
        this.root = root;
    }

    synchronized void open(String player) throws IOException
    {
        String safe = player == null ? "unknown" : player.replaceAll("[^A-Za-z0-9 _-]", "_").trim();
        if (safe.isEmpty())
        {
            safe = "unknown";
        }
        Filepath nextDirectory = root.joinSegment(safe.toLowerCase(java.util.Locale.ROOT)).rooted();
        nextDirectory.createDirectories();
        List<DeathRecord> nextRecords = new ArrayList<>();
        Filepath journal = nextDirectory.joinSegment("deaths.json");
        if (journal.exists())
        {
            try (Reader reader = journal.openBufferedReader())
            {
                DeathRecord[] loaded = gson.fromJson(reader, DeathRecord[].class);
                if (loaded != null)
                {
                    Collections.addAll(nextRecords, loaded);
                }
            }
        }
        directory = nextDirectory;
        records.clear();
        records.addAll(nextRecords);
    }

    synchronized void close()
    {
        directory = null;
        records.clear();
    }

    synchronized void add(DeathRecord record) throws IOException
    {
        records.add(0, record);
        save();
    }

    synchronized void save() throws IOException
    {
        if (directory == null)
        {
            return;
        }
        Filepath journal = directory.joinSegment("deaths.json");
        Filepath pending = directory.joinSegment("deaths.json.tmp");
        try (Writer writer = pending.openBufferedWriter())
        {
            gson.toJson(records.toArray(new DeathRecord[0]), DeathRecord[].class, writer);
        }
        try
        {
            pending.moveTo(journal, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
        }
        catch (java.nio.file.AtomicMoveNotSupportedException ex)
        {
            pending.moveTo(journal, StandardCopyOption.REPLACE_EXISTING);
        }
    }

    synchronized List<DeathRecord> records()
    {
        return Collections.unmodifiableList(new ArrayList<>(records));
    }

    synchronized Filepath imagePath(DeathRecord record)
    {
        return directory == null ? null : directory.joinSegment(record.id + ".png");
    }

    synchronized Filepath directory()
    {
        return directory;
    }
}

